const brands = $input.all().map(r => r.json).filter(r => r.brand_name && r.enabled !== 'FALSE');
return brands.map(b => ({ json: {
  brandName: b.brand_name.trim(),
  searchTerms: (b.search_terms || b.brand_name).split(',').map(s => s.trim()).filter(Boolean),
  alertEmail: b.alert_email || '',
  alertSlack: b.alert_slack || '',
  crisisThreshold: parseInt(b.crisis_threshold) || 5,
  industry: b.industry || '',
  competitors: (b.competitors || '').split(',').map(s => s.trim()).filter(Boolean)
} }));

const brand = $('Loop Each Brand').first().json;
const negResults = $('Search Negative Mentions').first().json?.results || [];
const newsResults = $('Search General News').first().json?.results || [];
const allResults = [...negResults, ...newsResults];
const unique = allResults.filter((r, i, arr) => arr.findIndex(x => x.url === r.url) === i);

const negKeywords = ['scandal', 'controversy', 'lawsuit', 'boycott', 'outrage', 'backlash', 'complaint', 'problem', 'fail', 'crisis', 'recall', 'breach', 'hack', 'fraud', 'mislead', 'discriminat', 'harass', 'abuse', 'fire', 'resign', 'bankrupt', 'shutdown'];
const posKeywords = ['award', 'launch', 'partnership', 'growth', 'funding', 'expansion', 'recognition', 'milestone'];

const scoredResults = unique.map(r => {
  const text = `${r.title} ${r.content || r.snippet || ''}`.toLowerCase();
  const negScore = negKeywords.filter(k => text.includes(k)).length;
  const posScore = posKeywords.filter(k => text.includes(k)).length;
  const brandMentioned = brand.searchTerms.some(t => text.includes(t.toLowerCase()));
  return { ...r, negScore, posScore, brandMentioned, netSentiment: posScore - negScore };
});

const negativeItems = scoredResults.filter(r => r.negScore > 0 && r.brandMentioned).sort((a,b) => b.negScore - a.negScore);
const positiveItems = scoredResults.filter(r => r.posScore > 0 && r.brandMentioned && r.negScore === 0);
const totalNegScore = negativeItems.reduce((s,r) => s + r.negScore, 0);
const crisisLevel = totalNegScore >= brand.crisisThreshold * 2 ? 'critical' : totalNegScore >= brand.crisisThreshold ? 'elevated' : negativeItems.length > 0 ? 'watch' : 'clear';

return [{ json: {
  brand,
  negativeItems: negativeItems.slice(0, 6),
  positiveItems: positiveItems.slice(0, 3),
  totalNegScore,
  crisisLevel,
  checkedAt: new Date().toISOString(),
  totalMentions: unique.filter(r => r.brandMentioned).length
} }];

values.content:
Assess this brand monitoring report and give response recommendations.

Brand: {{ $json.brand.brandName }}
Industry: {{ $json.brand.industry || 'not specified' }}
Crisis level: {{ $json.crisisLevel.toUpperCase() }}
Negative signal score: {{ $json.totalNegScore }}
Total mentions found: {{ $json.totalMentions }}
Checked: {{ $json.checkedAt }}

Negative/concerning items:
{{ $json.negativeItems.map(r => `- ${r.title} (score: ${r.negScore}): ${(r.content||r.snippet||'').slice(0,150)}`).join('\n') || 'none' }}

Positive/neutral news:
{{ $json.positiveItems.map(r => `- ${r.title}`).join('\n') || 'none' }}

Give: (1) what's actually happening and how serious it is, (2) whether this is noise or a genuine threat requiring action, (3) specific recommended next steps for the comms team right now.

