const analysis = $('Claude Crisis Analyst').first().json.text || $('Claude Crisis Analyst').first().json.content?.[0]?.text || '';
const d = $('Score Crisis Level').first().json;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const levelConfig = {
  critical: {color:'#dc2626', bg:'#fef2f2', label:'CRITICAL', emoji:'🚨'},
  elevated: {color:'#d97706', bg:'#fffbeb', label:'ELEVATED', emoji:'⚠️'},
  watch:    {color:'#2563eb', bg:'#eff6ff', label:'WATCH', emoji:'👁️'},
  clear:    {color:'#16a34a', bg:'#f0fdf4', label:'CLEAR', emoji:'✅'}
};
const lc = levelConfig[d.crisisLevel] || levelConfig.watch;

const negRows = d.negativeItems.map(item => `
  <div style="border-left:3px solid ${lc.color};padding:10px 14px;background:#fafafa;border-radius:0 6px 6px 0;margin-bottom:8px">
    <div style="font-size:14px;font-weight:600;color:#1a1a1a">${esc(item.title)}</div>
    <div style="font-size:12px;color:#9ca3af;margin-top:2px">${esc((item.content||item.snippet||'').slice(0,160))}</div>
    <div style="font-size:11px;color:${lc.color};margin-top:3px;font-weight:700">Signal strength: ${item.negScore}</div>
  </div>`).join('');

const posRows = d.positiveItems.map(item => `
  <div style="font-size:13px;color:#374151;padding:5px 0;border-bottom:1px solid #f0fdf4">✓ ${esc(item.title)}</div>`).join('');

const analysisHtml = analysis.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/
/g,'<br>');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:660px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:18px 26px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:4px">Crisis Monitor · ${esc(d.checkedAt.split('T')[0])}</div>
    <div style="font-size:18px;font-weight:700">${lc.emoji} ${esc(d.brand.brandName)} — ${lc.label}</div>
    <div style="font-size:13px;color:#9ca3af;margin-top:3px">${d.negativeItems.length} negative signals · ${d.totalMentions} mentions found</div>
  </div>
  <div style="background:${lc.bg};padding:14px 26px;border:1px solid ${lc.color}44;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:${lc.color};margin-bottom:7px">PR Analysis</div>
    <p style="font-size:14px;line-height:1.75;color:#374151;margin:0">${analysisHtml}</p>
  </div>
  ${negRows ? `<div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Concerning signals</div>
    ${negRows}
  </div>` : ''}
  ${posRows ? `<div style="background:#f0fdf4;padding:14px 26px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:7px">Positive news</div>
    ${posRows}
  </div>` : ''}
  <div style="background:#111827;color:#4b5563;font-size:11px;padding:10px 26px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Crisis Monitor · ${esc(d.brand.brandName)} · ${esc(d.checkedAt.replace('T',' ').slice(0,16))} UTC
  </div>
</div></body></html>`;

return [{ json: { html, brand: d.brand, crisisLevel: d.crisisLevel, alertEmail: d.brand.alertEmail, alertSlack: d.brand.alertSlack } }];

